{
  "items": [
    {
      "name": "MvPowerSeries.order",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [Semiring R] → MvPowerSeries σ R → ℕ∞"
    },
    {
      "name": "MvPowerSeries.order_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {d : σ →₀ ℕ} {a : R} [inst_1 : Decidable (a = 0)],\n  ((MvPowerSeries.monomial d) a).order = if a = 0 then ⊤ else ↑(Finsupp.degree d)"
    },
    {
      "name": "PowerSeries.order_eq_order",
      "module_name": "Mathlib.RingTheory.PowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {φ : PowerSeries R}, φ.order = MvPowerSeries.order φ"
    },
    {
      "name": "MvPowerSeries.weightedOrder_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {d : σ →₀ ℕ} {a : R} [inst_1 : Decidable (a = 0)],\n  MvPowerSeries.weightedOrder w ((MvPowerSeries.monomial d) a) = if a = 0 then ⊤ else ↑((Finsupp.weight w) d)"
    },
    {
      "name": "MvPowerSeries.weightedOrder_le",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] (w : σ → ℕ) {f : MvPowerSeries σ R} {d : σ →₀ ℕ},\n  (MvPowerSeries.coeff d) f ≠ 0 → MvPowerSeries.weightedOrder w f ≤ ↑((Finsupp.weight w) d)"
    },
    {
      "name": "MvPowerSeries.le_order_smul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {f : MvPowerSeries σ R} {a : R}, f.order ≤ (a • f).order"
    },
    {
      "name": "MvPowerSeries.order_monomial_of_ne_zero",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {d : σ →₀ ℕ} {a : R},\n  a ≠ 0 → ((MvPowerSeries.monomial d) a).order = ↑(Finsupp.degree d)"
    },
    {
      "name": "MvPowerSeries.weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [Semiring R] → (σ → ℕ) → MvPowerSeries σ R → ℕ∞"
    }
  ]
}
